ound .15s}.deploy-btn:hover{transform:translateY(-2px);background:#efff92}.deploy-btn b{font-size:17px;font-weight:400}.overlay-note{font:8px var(--mono);letter-spacing:.08em;color:#aaa9a1;margin-top:13px}.overlay-note span{color:var(--lime);padding:0 4px}.overlay-stamp{position:absolute;right:22px;bottom:22px;font:8px/1.6 var(--mono);letter-spacing:.18em;text-align:right;color:#e1ded68c;border-right:1px solid var(--pink);padding-right:7px;transform:rotate(-5deg)}.result-overlay{justify-content:center;text-align:center;background:#111216c9;backdrop-filter:blur(3px)}.result-content h2{font-size:62px;margin:12px 0}.result-content h2 em{color:var(--lime)}.result-content .deploy-btn{margin:20px auto}.result-overlay.hidden{display:none}.arena-footer{height:35px;display:flex;align-items:end;justify-content:space-between;font:8px var(--mono);letter-spacing:.07em;color:#747579}.arena-footer b{color:#c1c0b9;font-weight:400}.footer-dot{display:inline-block;width:5px;height:5px;border-radius:50%;background:#b4d839;margin-right:5px}.intel-title{display:flex;justify-content:space-between;padding:4px 0 10px;border-bottom:1px solid #ffffff1a}.brief-mark{color:var(--lime);font-size:16px;line-height:10px}.mission-card{padding:15px 14px 13px;background:linear-gradient(140deg,#1d1e21,#191a1d);border:1px solid #ffffff13;position:relative;margin:10px 0 20px;overflow:hidden}.mission-card:after{content:'♚';position:absolute;right:0;top:20px;font-size:92px;line-height:1;color:#ffffff07}.mission-number{font:10px var(--mono);color:var(--lime);position:relative;z-index:1}.mission-number span{color:#77787b}.mission-card h3{font:800 26px/.94 var(--display);margin:9px 0;letter-spacing:.03em;position:relative;z-index:1}.mission-card p{font-size:10px;line-height:1.6;color:#9e9ea0;max-width:185px;margin:0 0 14px;position:relative;z-index:1}.mission-objective{border-top:1px solid #ffffff16;padding-top:10px;display:flex;flex-direction:column;gap:5px;font:8px var(--mono);color:#828386;position:relative;z-index:1}.mission-objective b{font-size:8px;color:#d4d2cc;font-weight:400;letter-spacing:.04em}.mission-objective b i{font-size:15px;color:var(--lime);font-style:normal;vertical-align:-2px;margin-right:3px}.combat-log-head{display:flex;justify-content:space-between;align-items:center;padding-bottom:9px;border-bottom:1px solid #ffffff1a}.log-live{color:#d2d0c8;font-size:8px}.log-live i{display:inline-block;width:5px;height:5px;border-radius:50%;background:var(--pink);margin-right:4px;box-shadow:0 0 6px var(--pink)}.combat-log{height:102px;overflow:hidden;padding:7px 0}.log-entry{display:flex;gap:8px;padding:4px 0;font:8px/1.3 var(--mono);color:#bdbbb5;animation:log-in .2s ease-out}.log-entry time{color:#6e7074;flex:none}.log-entry strong{color:var(--lime);font-weight:400}.log-entry.enemy strong{color:var(--pink)}.log-entry.dim{color:#66686b}@keyframes log-in{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:translateY(0)}}.key-guide{border-top:1px solid #ffffff19;padding-top:12px}.guide-title{margin-bottom:10px}.key-guide>div:not(.guide-title){display:flex;align-items:center;gap:3px;margin:7px 0}.key-guide kbd{font:8px var(--mono);min-width:19px;height:18px;text-align:center;padding:3px 4px;background:#252629;border:1px solid #ffffff16;color:#c8c6c0}.key-guide>div span{font:8px var(--mono);letter-spacing:.05em;color:#9b9b9d;margin-left:auto}.key-guide>div kbd+span{margin-left:8px}.danger-note{display:flex;gap:9px;border-top:1px solid #ffffff19;margin-top:16px;padding-top:12px}.danger-note>span{width:16px;height:16px;border:1px solid #ff546f66;color:var(--pink);font:11px var(--mono);display:grid;place-items:center;flex:none}.danger-note p{font-size:9px;line-height:1.5;color:#8c8c8e;margin:0}.danger-note p b{font:8px var(--mono);letter-spacing:.06em;color:#d2d0ca}.page-footer{height:36px;border-top:1px solid #ffffff16;display:flex;justify-content:space-between;align-items:center;font:8px var(--mono);letter-spacing:.08em;color:#6c6d71}.page-footer b{col