d #d8ff3f94;box-shadow:0 0 15px #d8ff3f20}.touch-pad small{position:absolute;bottom:8px;font:7px var(--mono);letter-spacing:.1em;color:#ffffffa6}.touch-action{position:absolute;z-index:4;bottom:26px;border:1px solid #ffffff65;color:#fff;background:#141519ad;font:8px var(--mono);letter-spacing:.05em;touch-action:none}.dash-touch{right:86px;width:50px;height:50px;border-radius:50%;font-size:7px}.dash-touch span{display:block;color:var(--lime);font-size:6px;margin-top:3px}.fire-touch{right:18px;width:63px;height:63px;border-radius:50%;background:#d8ff3fdb;color:#161710;border:0;font-weight:700;font-size:8px}.fire-touch span{display:block;font-size:17px;line-height:17px}.crosshair-hint{display:none}.mobile-aim{display:block;position:absolute;z-index:3;top:18px;right:17px;font:7px var(--mono);color:#ffffff9a;letter-spacing:.1em}.overlay-card{margin-left:7%;max-width:260px}.overlay-kicker{font-size:8px}.overlay h2{font-size:55px;margin:14px 0}.overlay-card p{font-size:10px}.deploy-btn{height:39px;min-width:190px;font-size:9px;margin-top:17px}.overlay-note{font-size:6px}.overlay-stamp{font-size:6px;right:13px;bottom:14px}.page-footer{font-size:6px;height:30px}.page-footer span:last-child{display:none}}
