(() => {
  const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');
  const rosterEl=document.querySelector('#roster'), frame=document.querySelector('#arenaFrame');
  const roles=[
    {id:'queen',name:'THE QUEEN',piece:'♕',class:'CLASS 02 / ASSAULT',quote:'“Own every angle.”',weapon:'CROWN / AR',icon:'⌁',hp:100,rate:78,mob:85,speed:210,mag:24,fire:.13,damage:13,spread:.045,pellets:1,color:'#d8ff3f',ammo:'5.56'},
    {id:'king',name:'THE KING',piece:'♔',class:'CLASS 01 / COMMAND',quote:'“One shot. One order.”',weapon:'SOVEREIGN / HC',icon:'♜',hp:125,rate:42,mob:58,speed:168,mag:8,fire:.42,damage:29,spread:.018,pellets:1,color:'#79d8ff',ammo:'.45'},
    {id:'rook',name:'THE ROOK',piece:'♖',class:'CLASS 03 / BREACHER',quote:'“Make an entrance.”',weapon:'CASTLE / SG',icon:'▤',hp:115,rate:58,mob:65,speed:182,mag:6,fire:.62,damage:8,spread:.25,pellets:7,color:'#ff9d55',ammo:'12G'},
    {id:'bishop',name:'THE BISHOP',piece:'♗',class:'CLASS 04 / RECON',quote:'“Patience is a weapon.”',weapon:'MITRE / DMR',icon:'╱',hp:85,rate:51,mob:74,speed:192,mag:7,fire:.52,damage:38,spread:.012,pellets:1,color:'#b794ff',ammo:'.308'},
    {id:'knight',name:'THE KNIGHT',piece:'♘',class:'CLASS 05 / SKIRMISH',quote:'“You can’t catch a move.”',weapon:'LANCER / SMG',icon:'⌁',hp:90,rate:93,mob:100,speed:245,mag:32,fire:.085,damage:8,spread:.09,pellets:1,color:'#ff6e9a',ammo:'9MM'}
  ];
  const enemyTypes=[{piece:'♟',name:'PAWN',hp:32,speed:92,damage:8,color:'#ff5570',radius:15},{piece:'♞',name:'KNIGHT',hp:48,speed:120,damage:10,color:'#ff835a',radius:17},{piece:'♜',name:'ROOK',hp:76,speed:67,damage:13,color:'#ef4c91',radius:20},{piece:'♝',name:'BISHOP',hp:40,speed:76,damage:14,color:'#ad74ff',radius:16}];
  const obstacles=[{x:216,y:142,w:148,h:54,c:'#ef704b'},{x:637,y:119,w:118,h:90,c:'#48a3a0'},{x:424,y:210,w:133,h:57,c:'#d9b746'},{x:174,y:375,w:106,h:92,c:'#b55877'},{x:714,y:373,w:118,h:91,c:'#537fc1'},{x:421,y:464,w:158,h:65,c:'#e48542'},{x:328,y:338,w:71,h:44,c:'#7d9e47'},{x:612,y:287,w:70,h:45,c:'#966bb2'}];
  const state={role:roles[0],running:false,started:false,over:false,wave:0,score:0,kills:0,actors:[],bullets:[],particles:[],pickups:[],keys:{},mouse:{x:650,y:320,down:false},touchFire:false,last:0,elapsed:0,spawnTimer:0,remaining:0,transit:0,shake:0,log:[],sound:true};
  let W=1000,H=675,dpr=1,player=null;
  const rand=(a,b)=>a+Math.random()*(b-a), clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  const $=s=>document.querySelector(s);
  function log(text,type=''){const el=document.createElement('div');el.className='log-entry '+type;el.innerHTML=`<time>${String(Math.floor(state.elapsed/60)).padStart(2,'0')}:${String(Math.floor(state.elapsed%60)).padStart(2,'0')}</time><span>${text}</span>`;const box=$('#combatLog');box.prepend(el);while(box.children.length>6)box.lastChild.remove()}
  function choose(role){state.role=role;document.documentElement.style.setProperty('--class-color',role.color);$('#operatorClass').textContent=role.class;$('#operatorName').textContent=role.name;$('#operatorQuote').textContent=role.quote;$('#artPiece').textContent=role.piece;$('#weaponName').textContent=role.weapon;$('#weaponIcon').textContent=role.icon;$('#statHealth').style.width=role.hp/125*100+'%';$('#statRate').style.width=role.rate+'%';$('#statMobility').style.width=role.mob+'%';$('#statHealthText').textContent=role.hp;$('#statRateText').textContent=role.rate;$('#statMobilityText').textContent=role.mob;[...rosterEl.children].forEach((el,i)=>el.classList.toggle('active',roles[i]===role));if(player&&!state.running){player.role=role;player.maxHp=role.hp;player.hp=role.hp;player.speed=role.speed;player.mag=role.mag;player.ammo=role.mag;}}
  roles.forEach((r,i)=>{const b=document.createElement('button');b.className='piece-choice'+(!i?' active':'');b.innerHTML=`${r.piece}<small>0${i+1}</small>`;b.title=r.name+' — '+r.weapon;b.setAttribute('aria-label',r.name);b.onclick=()=>choose(r);rosterEl.append(b)});
