node --input-type=module <<'JS'
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime=process.env.HOME+'/.local/share/omgithub-playwright';
const require=createRequire(runtime+'/package.json');
const { chromium }=require('playwright');
const config=JSON.parse(readFileSync(runtime+'/linux.json','utf8'));
const browser=await chromium.launch(config.browser.launchOptions);
for (const viewport of [{width:1440,height:900},{width:390,height:844}]) {
 const page=await browser.newPage({viewport}); const errors=[];
 page.on('pageerror',e=>errors.push(e.message)); await page.goto('http://localhost:3000');
 const metrics=await page.evaluate(()=>({vw:innerWidth,sw:document.documentElement.scrollWidth, shell:document.querySelector('.shell').getBoundingClientRect().width,rail:document.querySelector('.rail').getBoundingClientRect().toJSON(),roster:document.querySelector('#roster').getBoundingClientRect().toJSON(),frame:document.querySelector('#arenaFrame').getBoundingClientRect().toJSON()}));
 await page.click('#roster button[aria-label="THE KNIGHT"]'); await page.click('#startButton');
 await page.waitForTimeout(1000);
 const gameplay=await page.evaluate(()=>({wave:document.querySelector('#waveText').textContent,status:document.querySelector('#statusText').textContent,canvas:[document.querySelector('#game').width,document.querySelector('#game').height],log:document.querySelector('#combatLog').innerText}));
 console.log(JSON.stringify({viewport,metrics,gameplay,errors})); await page.close();
}
await browser.close();
